"""AutoWSGR 异常层级体系。

层级树::

    AutoWSGRError
    ├── ConfigError
    ├── EmulatorError
    │   ├── EmulatorConnectionError
    │   │   └── DeviceError         # 设备级故障：连接/截图/分辨率
    │   └── EmulatorNotFoundError
    ├── VisionError
    │   ├── ImageNotFoundError
    │   └── OCRError
    ├── UIError
    │   ├── PageNotFoundError
    │   ├── NavigationError
    │   │   ├── PageNotRecognizedError
    │   │   └── PageDriftError       # 页面漂移（StuckError 为兼容别名）
    │   └── ActionFailedError
    ├── UIVersionError              # UI 版本不符：模板全灭 / 严重失配
    ├── GameError
    │   ├── DockFullError
    │   └── ResourceError
    ├── CombatError
    │   ├── CombatRecognitionTimeoutError
    │   └── CombatDecisionError
    └── CriticalError

三类错误构成「错误分级」接口（批次 4.3），供服务端与前端区分重试策略：

- :class:`PageDriftError`：可自动恢复（看门狗捕获的页面漂移）；
- :class:`UIVersionError`：需人工更新模板（全量识别最大得分低于阈值）；
- :class:`DeviceError`：设备/连接级故障（截图黑屏、scrcpy 断开）。

每个类都带 ``error_code`` / ``user_message`` 类属性，服务端用
:func:`get_graded_error_info` 统一取出，前端无需解析异常字符串。
"""

from __future__ import annotations

from typing import TYPE_CHECKING


if TYPE_CHECKING:
    from collections.abc import Sequence

    import numpy as np


# ── 基类 ──


class AutoWSGRError(Exception):
    """所有 AutoWSGR 异常的基类。"""


# ── 基础设施异常 ──


class ConfigError(AutoWSGRError):
    """配置错误（文件缺失、字段非法等）。"""


# ── 模拟器异常 ──


class EmulatorError(AutoWSGRError):
    """模拟器操作失败。"""


class EmulatorConnectionError(EmulatorError):
    """模拟器连接失败。"""


class EmulatorNotFoundError(EmulatorError):
    """未检测到模拟器。"""


# ── 设备级异常（批次 4.3）──


class DeviceError(EmulatorConnectionError):
    """设备连接/截图级故障，需要人工检查模拟器。

    与普通 :class:`NavigationError` 的区别：本异常发生时**拿不到可用画面**，
    继续重试导航没有意义。典型场景：scrcpy 连接断开、截图超时（黑屏/无帧）、
    分辨率彻底不可用。

    继承 :class:`EmulatorConnectionError` 是为了兼容既有的
    ``except EmulatorConnectionError`` 调用点；错误分级以 ``error_code``
    和具体类型名为准。

    Attributes
    ----------
    operation:
        触发失败的操作名（``connect`` / ``screenshot`` / ``stream`` 等）。
    error_code:
        稳定的机器可读错误码，服务端写入 ``result_summary``。
    user_message:
        面向用户的中文提示，前端可直接展示。
    """

    error_code = 'device'
    user_message = '设备连接异常，请检查模拟器是否运行'

    def __init__(self, reason: str = '设备连接或截图失败', *, operation: str = '') -> None:
        self.reason = reason
        self.operation = operation
        msg = f'设备异常: {reason}'
        if operation:
            msg += f' ({operation})'
        super().__init__(msg)


# ── 视觉层异常 ──


class VisionError(AutoWSGRError):
    """视觉识别相关错误。"""


class OCRError(VisionError):
    """OCR 识别失败。"""


class ImageNotFoundError(VisionError):
    """模板图像在屏幕上未找到。"""

    def __init__(self, template_name: str = '', timeout: float = 0) -> None:
        self.template_name = template_name
        self.timeout = timeout
        msg = f'未找到图像: {template_name}'
        if timeout:
            msg += f' (超时 {timeout:.1f}s)'
        super().__init__(msg)


# ── UI 层异常 ──


class UIError(AutoWSGRError):
    """UI 操作相关错误。"""


class PageNotFoundError(UIError):
    """无法识别当前页面。"""


class NavigationError(UIError):
    """页面导航验证失败 - 超时未到达目标页面，或重试耗尽。

    这是导航失败的**唯一基类**：``ui.utils`` 通过 import 复用本类，
    不再维护第二份同名异常，``except NavigationError`` 才能同时接住
    :class:`PageNotRecognizedError` 与 :class:`PageDriftError`。

    Attributes
    ----------
    screenshot_path:
        失败现场截图的落盘路径（未保存时为 ``None``）。
    """

    def __init__(self, msg: str = '', screen: np.ndarray | None = None) -> None:
        self.screenshot_path: str | None = None
        if screen is not None:
            from autowsgr.infra.logger import save_image

            saved = save_image(screen, tag='NavError')
            if saved is not None:
                self.screenshot_path = str(saved)
        super().__init__(msg)


class PageNotRecognizedError(NavigationError):
    """当前画面无法识别为任何已知页面（UNKNOWN_PAGE）。

    与普通 :class:`NavigationError` 的区别在于**语义**：普通失败是「知道在哪、
    但走不过去」（路径缺失、步数超限、点击没生效）；本异常是「根本不知道在哪」。

    两者需要分开，因为恢复手段不同——不知道在哪时，先试着点游戏内的「◁」回退
    一层往往最有效；而知道在哪却走不过去时，回退只会让局面更乱。

    继承 ``NavigationError`` 是为了不破坏既有 ``except NavigationError`` 调用点。
    """


class PageDriftError(NavigationError):
    """页面漂移：BFS 路径通，但分数偏低或在同一页反复卡住。

    与普通 :class:`NavigationError` 的区别：本异常由**跨轮次的模式**触发，
    不是某一次点击超时（看门狗：同页同动作 3 次 / 同页 12 步 / 连败 5 次 /
    12 步未达目标）。它必须携带页面/动作轨迹，否则日志只能看到一句
    「导航失败」，无法判断是模板误判、弹窗遮挡还是点击坐标漂移。

    这类错误属于**可自动恢复**级别：调用方可选择重试、清理弹窗或重新规划；
    只有反复出现时才需要人工介入。

    Attributes
    ----------
    page_trail:
        最近若干步经过的页面（旧的在前，最多 15 步）。
    action_trail:
        与 ``page_trail`` 对齐的动作名（旧的在前）。
    target:
        本次导航目标页。
    reason:
        命中的具体看门狗规则。
    """

    error_code = 'page_drift'
    user_message = '页面漂移，可自动恢复；若反复出现请重试'

    def __init__(
        self,
        reason: str,
        *,
        target: str = '',
        page_trail: Sequence[str] | None = None,
        action_trail: Sequence[str] | None = None,
        screen: np.ndarray | None = None,
    ) -> None:
        self.target = target
        self.reason = reason
        self.page_trail = list(page_trail or ())
        self.action_trail = list(action_trail or ())

        msg = f'页面漂移(导航卡死): {reason}'
        if target:
            msg += f' (目标: {target})'
        if self.page_trail:
            msg += f'；最近页面轨迹: {" → ".join(self.page_trail)}'
        if self.action_trail:
            msg += f'；最近动作轨迹: {" → ".join(self.action_trail)}'
        super().__init__(msg, screen=screen)


# 4.6 的异常名保留为兼容别名：4.3 起看门狗统一抛 PageDriftError，
# 旧的 ``except StuckError`` / ``from ... import StuckError`` 仍然成立，
# 且 ``type(error).__name__`` 是 ``PageDriftError``（错误分级以新类型为准）。
StuckError = PageDriftError


class UIVersionError(AutoWSGRError):
    """UI 版本不符：所有页面识别器全灭，或核心模板严重失配。

    判据由 :func:`autowsgr.ui.page.get_current_page` 在**全量识别**且
    最高得分低于 :data:`autowsgr.ui.page.UI_VERSION_MAX_SCORE` 时给出。
    这类错误不是重试能解决的：通常意味着游戏客户端更新、模板过期或
    截图被整屏遮挡，需要人工更新模板/检查画面。

    Attributes
    ----------
    max_score:
        本次全量识别的最高得分（没有可用结果时为 0）。
    threshold:
        判定阈值（默认 0.4）。
    evaluated:
        参与评估的页面识别器数量。
    top_matches:
        得分最高的若干页面摘要（``名称=分数/thr=阈值``），用于日志取证。
    """

    error_code = 'ui_version'
    user_message = '游戏可能更新，请更新模板'

    def __init__(
        self,
        reason: str = '全量识别最大得分低于阈值',
        *,
        max_score: float = 0.0,
        threshold: float = 0.4,
        evaluated: int = 0,
        top_matches: Sequence[str] | None = None,
    ) -> None:
        self.reason = reason
        self.max_score = max_score
        self.threshold = threshold
        self.evaluated = evaluated
        self.top_matches = list(top_matches or ())
        msg = f'UI 版本不符: {reason}'
        if evaluated:
            msg += f' (最高分 {max_score:.3f} < {threshold:.2f}，评估 {evaluated} 个页面)'
        if self.top_matches:
            msg += f'；Top: {", ".join(self.top_matches)}'
        super().__init__(msg)


class TaskStopRequested(AutoWSGRError):
    """用户请求停止任务。

    与 :class:`~autowsgr.combat.recognizer.CombatStopRequestedError` 的区别：
    后者只在战斗状态识别循环内抛出（本就是引擎的退出信号），
    本异常用于**非战斗阶段**的中断——导航、出征准备、多轮循环之间。

    单独成类是为了让上层能区分「用户让停」与「真失败」：前者应当静默中止、
    不计入失败统计，后者才需要报错重试。
    """

    def __init__(self, stage: str = '') -> None:
        self.stage = stage
        super().__init__(f'任务被用户停止 (阶段: {stage})' if stage else '任务被用户停止')


class ActionFailedError(UIError):
    """UIAction 执行失败。"""

    def __init__(self, action_name: str, reason: str = '') -> None:
        self.action_name = action_name
        msg = f'操作失败: {action_name}'
        if reason:
            msg += f' ({reason})'
        super().__init__(msg)


class ChapterResetError(ActionFailedError):
    """章节重置失败（「船坞已满」以外的原因）。

    磁盘不足、网络重试、确认弹窗变体、点击未生效在画面上都表现为
    「入口状态没有变成已重置」，只能靠截图区分。因此本异常在构造时
    保存失败现场截图，并把落盘路径写进消息与 ``screenshot_path``，
    避免调用方一律把失败当成 :class:`DockFullError`。

    Attributes
    ----------
    screenshot_path:
        失败现场截图的落盘路径（未保存时为 ``None``，如未开启图片保存）。
    """

    error_code = 'chapter_reset'
    user_message = '章节重置失败（非船坞满），请查看截图确认原因'

    def __init__(self, reason: str, *, screen: np.ndarray | None = None) -> None:
        self.screenshot_path: str | None = None
        if screen is not None:
            from autowsgr.infra.logger import save_image

            saved = save_image(screen, tag='ChapterResetFailed')
            if saved is not None:
                self.screenshot_path = str(saved)
        detail = reason
        if self.screenshot_path:
            detail = f'{reason}；截图: {self.screenshot_path}'
        super().__init__('reset_chapter', detail)


# ── 游戏逻辑异常 ──


class GameError(AutoWSGRError):
    """游戏逻辑错误。"""


class NetworkError(GameError):
    """游戏网络错误（断线、卡顿）。"""


class DockFullError(GameError):
    """船坞已满。"""


class ResourceError(GameError):
    """资源不足。"""


# ── 战斗系统异常 ──


class CombatError(AutoWSGRError):
    """战斗系统错误。"""


class CombatRecognitionTimeoutError(CombatError):
    """战斗状态识别超时。"""

    def __init__(self, candidates: list[str] | None = None, timeout: float = 0) -> None:
        self.candidates = candidates or []
        self.timeout = timeout
        names = ', '.join(self.candidates)
        super().__init__(f'战斗状态识别超时 ({timeout:.1f}s): [{names}]')


class CombatDecisionError(CombatError):
    """战斗决策错误（规则配置问题等）。"""


# ── 不可恢复错误 ──


class CriticalError(AutoWSGRError):
    """不可恢复的严重错误，需要终止。"""


# ── 错误分级统一出口（批次 4.3）──

_GRADED_ERROR_CLASSES: tuple[type[AutoWSGRError], ...] = (
    PageDriftError,
    UIVersionError,
    DeviceError,
)


def get_graded_error_info(
    error: BaseException,
) -> dict[str, str] | None:
    """把三类分级异常归一化成服务端/前端可直接消费的元数据。

    Returns
    -------
    dict | None
        ``{error_code, error_type, error_hint}``；非分级异常返回 ``None``。
        ``PageDriftError`` 的子类/别名（含旧的 ``StuckError``）同样命中。
    """
    for error_class in _GRADED_ERROR_CLASSES:
        if isinstance(error, error_class):
            return {
                'error_code': error_class.error_code,
                'error_type': type(error).__name__,
                'error_hint': error_class.user_message,
            }
    return None
